package ma.mystix.atelys.mobile

import android.content.Context
import android.os.Build
import java.util.UUID
import ma.mystix.mobile.devicehub.CapabilityIds
import ma.mystix.mobile.devicehub.CapabilitySource
import ma.mystix.mobile.devicehub.DeviceCapability
import ma.mystix.mobile.devicehub.DeviceDescriptor
import ma.mystix.mobile.devicehub.DeviceDetector
import ma.mystix.mobile.devicehub.DeviceSnapshot
import ma.mystix.mobile.devicehub.ScannerAvailability

/**
 * Reads what Android declares (android.os.Build) and an installation id generated by Atelys. No IMEI, no serial
 * number, no Android ID. The scan service state is UNKNOWN: neither adapter of this build can query it.
 */
class AndroidDeviceDetector(private val context: Context) : DeviceDetector {
    private val prefs = context.getSharedPreferences("atelys.device", Context.MODE_PRIVATE)

    val installationId: String
        @Synchronized get() = prefs.getString(KEY_INSTALLATION, null)
            ?: UUID.randomUUID().toString().also { prefs.edit().putString(KEY_INSTALLATION, it).apply() }

    override fun detect(): DeviceSnapshot {
        val device = DeviceDescriptor(
            installationId = installationId,
            manufacturer = Build.MANUFACTURER.orEmpty(),
            brand = Build.BRAND.orEmpty(),
            model = Build.MODEL.orEmpty(),
            product = Build.PRODUCT.orEmpty(),
            androidRelease = Build.VERSION.RELEASE.orEmpty(),
            sdkInt = Build.VERSION.SDK_INT,
            buildId = Build.ID.orEmpty(),
            appVersion = appVersion(),
        )
        val capabilities = listOf(
            DeviceCapability(CapabilityIds.KEY_EVENTS, CapabilitySource.DETECTED, "Activity key dispatch"),
        )
        return DeviceSnapshot(device, capabilities, ScannerAvailability.UNKNOWN, System.currentTimeMillis())
    }

    private fun appVersion(): String = runCatching {
        context.packageManager.getPackageInfo(context.packageName, 0).versionName
    }.getOrNull() ?: "unknown"

    private companion object {
        const val KEY_INSTALLATION = "installationId"
    }
}
